17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.time.DayOfWeek;
23	import java.time.LocalDate;
24	import java.util.Collection;
25	import java.util.Comparator;
26	import java.util.List;
27	import java.util.Map;
28	
29	import org.slf4j.Logger;
30	import org.slf4j.LoggerFactory;
31	import org.springframework.http.HttpHeaders;
32	import org.springframework.http.HttpStatus;
33	import org.springframework.http.ResponseEntity;
34	import org.springframework.samples.petclinic.mapper.OwnerMapper;
35	import org.springframework.samples.petclinic.mapper.PetMapper;
36	import org.springframework.samples.petclinic.mapper.VisitMapper;
37	import org.springframework.samples.petclinic.model.Owner;
38	import org.springframework.samples.petclinic.model.Pet;
39	import org.springframework.samples.petclinic.model.Visit;
40	import org.springframework.samples.petclinic.rest.api.OwnersApi;
41	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
42	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.PetDto;
44	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
47	import org.springframework.samples.petclinic.service.ClinicService;
48	import org.springframework.security.access.prepost.PreAuthorize;
49	import org.springframework.web.bind.annotation.CrossOrigin;
50	import org.springframework.web.bind.annotation.RequestMapping;
51	import org.springframework.web.bind.annotation.RestController;
52	import org.springframework.web.util.UriComponentsBuilder;
53	
54	import jakarta.transaction.Transactional;
55	
56	/**
57	 * @author Vitaliy Fedoriv
58	 */
59	
60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
66	
67	    private final ClinicService clinicService;
68	
69	    private final OwnerMapper ownerMapper;
70	
71	    private final PetMapper petMapper;
72	
73	    private final VisitMapper visitMapper;
74	
75	    private final AddressNormalizer addressNormalizer;
76	
77	    public OwnerRestControllerV1(ClinicService clinicService,
78	                                 OwnerMapper ownerMapper,
79	                                 PetMapper petMapper,
80	                                 VisitMapper visitMapper,
81	                                 AddressNormalizer addressNormalizer) {
82	        this.clinicService = clinicService;
83	        this.ownerMapper = ownerMapper;
84	        this.petMapper = petMapper;
85	        this.visitMapper = visitMapper;
86	        this.addressNormalizer = addressNormalizer;
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
92	        Collection<Owner> owners;
93	        if (lastName != null) {
94	            owners = this.clinicService.findOwnerByLastName(lastName);
95	        } else {
96	            owners = this.clinicService.findAllOwners();
97	        }
98	        if (owners.isEmpty()) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
107	        Owner owner = this.clinicService.findOwnerById(ownerId);
108	        if (owner == null) {
109	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
110	        }
111	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
112	    }
113	
114	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
115	    @Override
116	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
117	        HttpHeaders headers = new HttpHeaders();
118	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
119	        String address = addressNormalizer.normalize(owner.getAddress());
120	        if (address.isEmpty()) {
121	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
122	        }
123	        owner.setAddress(address);
124	        String telephone = toE164(owner.getTelephone());
125	        if (telephone == null) {
126	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
127	        }
128	        owner.setTelephone(telephone);
129	        if (!owner.isPostcodeValid()) {
130	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
131	        }
132	        if (owner.getRegistrationDate() != null
133	            && owner.getRegistrationDate().isAfter(LocalDate.now())) {
134	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
135	        }
136	        LocalDate effectiveDate = owner.getRegistrationDate() != null
137	            ? owner.getRegistrationDate() : LocalDate.now();
138	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
139	        if (isDailyLimitReached(owner.getRegistrationDate())) {
140	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
141	        }
142	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
143	        if (sharesHousehold) {
144	            owner.setHouseholdId(householdId(owner.getLastName(), owner.getAddress()));
145	        }
146	        if (isDuplicate(owner)) {
147	            return new ResponseEntity<>(HttpStatus.CONFLICT);
148	        }
149	        if (isCityAtCapacity(owner.getCity())) {
150	            return new ResponseEntity<>(HttpStatus.CONFLICT);
151	        }
152	        assignDerivedAttributes(owner);
153	        this.clinicService.saveOwner(owner);
154	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
155	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
156	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
157	        headers.setLocation(UriComponentsBuilder.newInstance()
158	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
159	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
160	    }
161	
162	    /**
163	     * Assign the attributes that are derived once, at creation time, and stored on the owner: its
164	     * {@link #customerCode(Owner) customerCode}, {@link #namesakeCount(String, String) namesakeCount},
165	     * {@link #isBulkSignup(LocalDate) bulk-signup warning} and {@link #householdSize(String)
166	     * householdSize}. Each is computed from the owner's own fields together with the owners already
167	     * present, so this runs after the owner has been validated and has passed the duplicate and
168	     * capacity checks, and immediately before it is persisted.
169	     */
170	    private void assignDerivedAttributes(Owner owner) {
171	        owner.setCustomerCode(customerCode(owner));
172	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
173	        owner.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
174	        owner.setHouseholdSize(householdSize(owner.getHouseholdId()));
175	        assignPossibleDuplicate(owner);
176	    }
177	
178	    /**
179	     * Flag a newly created owner as a possible (soft) duplicate. Because this runs after the hard
180	     * {@link #isDuplicate(Owner) duplicate} check, the owner is not an exact identity match; it is a
181	     * soft match when an existing owner shares its lastName (compared case-insensitively, with
182	     * collapsed whitespace) and its postcode but carries a different telephone. When such an owner
183	     * exists the new owner is flagged with {@code possibleDuplicate = true} and
184	     * {@code possibleDuplicateOf} set to the matching owner's id (the earliest such owner when more
185	     * than one matches); otherwise {@code possibleDuplicate = false} and no matching id is recorded.
186	     * A postcode is required for a soft match, so an owner without a postcode is never flagged.
187	     */
188	    private void assignPossibleDuplicate(Owner owner) {
189	        String candidateLastName = normalizeName(owner.getLastName());
190	        Owner match = owner.getPostcode() == null ? null
191	            : this.clinicService.findAllOwners().stream()
192	                .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
193	                .filter(existing -> normalizeName(existing.getLastName()).equals(candidateLastName))
194	                .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
195	                .min(Comparator.comparingInt(Owner::getId))
196	                .orElse(null);
197	        owner.setPossibleDuplicate(match != null);
198	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
199	    }
200	
201	    /**
202	     * Build the customer code for a newly created owner, formatted {@code '<REGION>-<HASH8>'}
203	     * where REGION is the region derived from the owner's postcode (or {@link Owner#UNKNOWN_REGION}
204	     * when the postcode is absent or maps to no known region) and HASH8 is the first 8 upper-case
205	     * hex characters of the SHA-256 of the normalized (E.164) telephone concatenated with the
206	     * lastName (e.g. {@code 'NSW-3C1A9F2B'}). This is the single source of the owner's identity:
207	     * every value built from the customer code (the membership number and its check digit) and the
208	     * owner's locality are derived from it.
209	     */
210	    private String customerCode(Owner owner) {
211	        String region = owner.getRegion() != null ? owner.getRegion() : Owner.UNKNOWN_REGION;
212	        String hash8 = shaHexUpper(owner.getTelephone() + owner.getLastName()).substring(0, 8);
213	        return region + "-" + hash8;
214	    }
215	
216	    /**
217	     * Whether the per-day owner creation limit has been reached for the given business day, i.e.
218	     * 100 or more owners already carry that {@code registrationDate}. The day is the adjusted
219	     * (business-day) registration date of the owner being created, so owners are counted per
220	     * business day. When true, a new owner must be rejected with {@code 429 Too Many Requests}.
221	     */
222	    private boolean isDailyLimitReached(LocalDate day) {
223	        long count = this.clinicService.findAllOwners().stream()
224	            .filter(existing -> day.equals(existing.getRegistrationDate()))
225	            .count();
226	        return count >= 100;
227	    }
228	
229	    /**
230	     * Whether creating this owner pushes the day's total past the bulk-signup threshold, i.e.
231	     * more than 80 owners have already been created for the given business day. Counts the owners
232	     * already carrying that {@code registrationDate} (the same accumulation as the daily-limit
233	     * rule); when that count exceeds 80 the newly created owner is flagged with a bulk-signup
234	     * warning.
235	     */
236	    private boolean isBulkSignup(LocalDate day) {
237	        long count = this.clinicService.findAllOwners().stream()
238	            .filter(existing -> day.equals(existing.getRegistrationDate()))
239	            .count();
240	        return count > 80;
241	    }
242	
243	    /**
244	     * Roll a registration date forward onto a business day: when it falls on a Saturday or Sunday,
245	     * advance it to the following Monday; a weekday is returned unchanged.
246	     */
247	    private LocalDate toBusinessDay(LocalDate date) {
248	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
249	            date = date.plusDays(1);
250	        }
251	        return date;
252	    }
253	
254	    /**
255	     * Whether the given city has reached its owner capacity, i.e. it already contains 50 or
256	     * more owners. Cities are compared case-insensitively.
257	     */
258	    private boolean isCityAtCapacity(String city) {
259	        long count = this.clinicService.findAllOwners().stream()
260	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
261	            .count();
262	        return count >= 50;
263	    }
264	
265	    /**
266	     * The number of existing owners that already share the given firstName and lastName,
267	     * compared case-insensitively (and with surrounding whitespace trimmed and internal
268	     * whitespace runs collapsed). Counted over the owners present before this create.
269	     */
270	    private int namesakeCount(String firstName, String lastName) {
271	        String candidateFirstName = normalizeName(firstName);
272	        String candidateLastName = normalizeName(lastName);
273	        return (int) this.clinicService.findAllOwners().stream()
274	            .filter(existing -> normalizeName(existing.getFirstName()).equals(candidateFirstName)
275	                && normalizeName(existing.getLastName()).equals(candidateLastName))
276	            .count();
277	    }
278	
279	    /**
280	     * The number of members in this owner's household after this create: the count of existing
281	     * owners already carrying the same non-null {@code householdId} plus one for the owner being
282	     * created. An owner with no household ({@code householdId == null}) is a household of one.
283	     * Owners sharing a household are matched by their assigned {@code householdId}, so the count
284	     * does not depend on the order in which household members were created.
285	     */
286	    private int householdSize(String householdId) {
287	        if (householdId == null) {
288	            return 1;
289	        }
290	        long existing = this.clinicService.findAllOwners().stream()
291	            .filter(other -> householdId.equals(other.getHouseholdId()))
292	            .count();
293	        return (int) existing + 1;
294	    }
295	
296	    /**
297	     * The number of national (subscriber) digits required for each known country calling
298	     * code, keyed by the code's digits (without the leading '+'). A number whose country
299	     * code appears here must carry exactly this many digits after the code, e.g. '+61'
300	     * requires 9 national digits and '+1' requires 10.
301	     */
302	    private static final Map<String, Integer> NATIONAL_DIGITS_BY_COUNTRY = Map.of(
303	        "1", 10,
304	        "61", 9);
305	
306	    /**
307	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
308	     * cannot form a valid E.164 number.
309	     *
310	     * <p>A leading '+' and country code are kept when present; otherwise country code
311	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
312	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
313	     * carry 8 to 15 digits after the '+', and — for a recognised country calling code —
314	     * exactly the national-digit count that code requires (see
315	     * {@link #NATIONAL_DIGITS_BY_COUNTRY}); otherwise it is rejected as invalid.
316	     */
317	    private String toE164(String telephone) {
318	        if (telephone == null) {
319	            return null;
320	        }
321	        boolean hasCountryCode = telephone.trim().startsWith("+");
322	        String digits = telephone.replaceAll("\\D", "");
323	        String e164;
324	        if (hasCountryCode) {
325	            e164 = digits;
326	        } else {
327	            if (digits.startsWith("0")) {
328	                digits = digits.substring(1);
329	            }
330	            e164 = "61" + digits;
331	        }
332	        if (e164.length() < 8 || e164.length() > 15) {
333	            return null;
334	        }
335	        if (!hasValidNationalLength(e164)) {
336	            return null;
337	        }
338	        return "+" + e164;
339	    }
340	
341	    /**
342	     * Whether the E.164 digit string (no leading '+') carries the national-number length
343	     * required by its country calling code. The longest matching known code wins; a number
344	     * whose country code is not recognised passes this check (its length is governed only by
345	     * the general 8-15 digit bound in {@link #toE164}).
346	     */
347	    private boolean hasValidNationalLength(String e164) {
348	        return NATIONAL_DIGITS_BY_COUNTRY.entrySet().stream()
349	            .filter(entry -> e164.startsWith(entry.getKey()))
350	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
351	            .map(entry -> e164.length() - entry.getKey().length() == entry.getValue())
352	            .orElse(true);
353	    }
354	
355	    /**
356	     * Whether the candidate owner duplicates an owner that already exists, and so must be
357	     * rejected with {@code 409 Conflict}. All duplicate detection is consolidated into a single
358	     * derived {@link Owner#getIdentityKey() identityKey} — the normalized telephone, email (or
359	     * empty) and householdId (or empty) joined with {@code '|'} — and an owner is a duplicate only
360	     * when its WHOLE identity key equals that of an existing owner. Because the telephone is part
361	     * of the key, two members of the same household with different telephones have different
362	     * identity keys and are both allowed; only an exact full-key match is a duplicate.
363	     */
364	    private boolean isDuplicate(Owner owner) {
365	        String identityKey = owner.getIdentityKey();
366	        return this.clinicService.findAllOwners().stream()
367	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
368	    }
369	
370	    /**
371	     * Normalize an owner's name for household comparison: trim, collapse internal whitespace runs
372	     * to a single space and lower-case. A null value normalizes to the empty string.
373	     */
374	    private String normalizeName(String value) {
375	        if (value == null) {
376	            return "";
377	        }
378	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
379	    }
380	
381	    /**
382	     * A stable shared identifier for the household formed by a given lastName and address.
383	     * Derived deterministically from the normalized (case-insensitive, whitespace-collapsed)
384	     * lastName and address, so every owner sharing the same household is assigned the same
385	     * value regardless of the order in which they are created. Formatted as the first 12
386	     * upper-case hex characters of the SHA-256 of {@code '<lastName>|<address>'}.
387	     */
388	    private String householdId(String lastName, String address) {
389	        String key = normalizeName(lastName) + "|" + addressNormalizer.normalize(address);
390	        return shaHexUpper(key).substring(0, 12);
391	    }
392	
393	    /**
394	     * The SHA-256 digest of {@code input}'s UTF-8 bytes, rendered as an upper-case hexadecimal
395	     * string (two hex characters per digest byte, so 64 characters in all). This is the single
396	     * place the hashing-and-hex-encoding is performed; callers that need a shorter opaque token
397	     * take a prefix of the result (e.g. {@link #householdId} keeps the first 12 characters and
398	     * {@link #customerCode} keeps the first 8).
399	     */
400	    private String shaHexUpper(String input) {
401	        try {
402	            byte[] digest = MessageDigest.getInstance("SHA-256")
403	                .digest(input.getBytes(StandardCharsets.UTF_8));
404	            StringBuilder sb = new StringBuilder(digest.length * 2);
405	            for (byte b : digest) {
406	                sb.append(String.format("%02x", b));
407	            }
408	            return sb.toString().toUpperCase();
409	        }
410	        catch (NoSuchAlgorithmException e) {
411	            throw new IllegalStateException("SHA-256 not available", e);
412	        }
413	    }
414	
415	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
416	    @Override
417	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
418	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
419	        if (currentOwner == null) {
420	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
421	        }
422	        currentOwner.setAddress(ownerFieldsDto.getAddress());
423	        currentOwner.setCity(ownerFieldsDto.getCity());
424	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
425	        currentOwner.setLastName(ownerFieldsDto.getLastName());
426	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
427	        this.clinicService.saveOwner(currentOwner);
428	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
429	    }
430	
431	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
432	    @Transactional
433	    @Override
434	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
435	        Owner owner = this.clinicService.findOwnerById(ownerId);
436	        if (owner == null) {
437	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
438	        }
439	        this.clinicService.deleteOwner(owner);
440	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
441	    }
442	
443	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
444	    @Override
445	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
446	        Owner owner = this.clinicService.findOwnerById(ownerId);
447	        if (owner == null) {
448	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
449	        }
450	        HttpHeaders headers = new HttpHeaders();
451	        Pet pet = petMapper.toPet(petFieldsDto);
452	        owner.setId(ownerId);
453	        pet.setOwner(owner);
454	        pet.getType().setName(null);
455	        this.clinicService.savePet(pet);
456	        PetDto petDto = petMapper.toPetDto(pet);
457	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
458	            .buildAndExpand(pet.getId()).toUri());
459	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
460	    }
461	
462	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
463	    @Override
464	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
465	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
466	        if (currentOwner != null) {
467	            Pet currentPet = this.clinicService.findPetById(petId);
468	            if (currentPet != null) {
469	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
470	                currentPet.setName(petFieldsDto.getName());
471	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
472	                this.clinicService.savePet(currentPet);
473	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
474	            }
475	        }
476	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
477	    }
478	
479	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
480	    @Override
481	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
482	        HttpHeaders headers = new HttpHeaders();
483	        Visit visit = visitMapper.toVisit(visitFieldsDto);
484	        Pet pet = new Pet();
485	        pet.setId(petId);
486	        visit.setPet(pet);
487	        this.clinicService.saveVisit(visit);
488	        VisitDto visitDto = visitMapper.toVisitDto(visit);
489	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
490	            .buildAndExpand(visit.getId()).toUri());
491	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
492	    }
493	
494	
495	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
496	    @Override
497	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
498	        Owner owner = this.clinicService.findOwnerById(ownerId);
499	        if (owner != null) {
500	            Pet pet = owner.getPet(petId);
501	            if (pet != null) {
502	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
503	            }
504	        }
505	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
506	    }
507	}
