135	        this.registrationDate = registrationDate;
136	    }
137	
138	    public LocalDate getBirthDate() {
139	        return this.birthDate;
140	    }
141	
142	    public void setBirthDate(LocalDate birthDate) {
143	        this.birthDate = birthDate;
144	    }
145	
146	    /**
147	     * The owner's age band derived from {@link #birthDate} relative to the
148	     * {@link #registrationDate}: {@code 'MINOR'} when under 18, {@code 'ADULT'} from 18 to 64,
149	     * and {@code 'SENIOR'} at 65 or older. Returns {@code null} when no birthDate is set. The age
150	     * is the number of complete years between the birthDate and the registrationDate (or the
151	     * current date when the registrationDate is not yet set).
152	     */
153	    public String getAgeBand() {
154	        if (this.birthDate == null) {
155	            return null;
156	        }
157	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
158	        int years = Period.between(this.birthDate, reference).getYears();
159	        if (years < 18) {
160	            return "MINOR";
161	        }
162	        if (years < 65) {
163	            return "ADULT";
164	        }
165	        return "SENIOR";
166	    }
167	
168	    public String getCustomerCode() {
169	        return this.customerCode;
170	    }
171	
172	    public void setCustomerCode(String customerCode) {
173	        this.customerCode = customerCode;
174	    }
175	
176	    public String getHouseholdId() {
177	        return this.householdId;
